      String[] parts = clipboardContent.split("/", 5);
      if (parts.length != 5) {
          logging.logToError("Invalid clipboard format. Expected 5 parts separated by '/'");
          return;
      }

      String protocol = parts[1];
      String host = parts[2];
      int port = Integer.parseInt(parts[3]);
