    + "|\\b[a-fA-F0-9]{64}\\b"
    + "|\\b[a-fA-F0-9]{40}\\b"
    + "|\\b[a-fA-F0-9]{32}\\b"
    + ")\\s*['\"]?";

Pattern hash_patterns = Pattern.compile(regex);

Matcher hash_matcher = hash_patterns.matcher(response_body);

