// Extract host and path from URL
String[] urlParts = requestUrl.split("/", 4);
String host = urlParts.length > 2 ? urlParts[2] : "";
String path = urlParts.length > 3 ? "/" + urlParts[3].split("\\?")[0] : "";

// Check for tracked host
