}

var cspValue = resp
    .headerValue(csp)
    .replaceAll("(report-uri|report-to)\\s+[^;]+", "report-to csp-reports");

return resp
    .withUpdatedHeader(csp, cspValue)
    .withRemovedHeader("Reporting-Endpoints")
    .withAddedHeader("Reporting-Endpoints", "csp-reports=\""+collaborator+"\"");

